import { z } from "zod";

import { byTitle, findRepeats } from "#shared/text/titles";

/** The most colors the gallery may have; raise it when the artist needs more. */
export const maxColors = 100;

/**
 * Every color of the gallery, as the client sends it to replace them all: a saved color left
 * out is deleted. The colors come in any order, and are kept sorted by title, as the site and the
 * admin list them.
 */
export const galleryColorsBodySchema = z
  .strictObject({
    colors: z
      .array(
        z.strictObject({
          /** Generated by the client, so a color keeps its id while it is renamed. */
          id: z.uuid(),
          title: z.string().trim().min(1).max(50),
          /** The swatch the site shows next to the title, as the browser color picker gives it. */
          hex: z
            .string()
            .regex(/^#[0-9a-f]{6}$/i, "Must be a color as #rrggbb")
            .transform((hex) => hex.toLowerCase()),
        }),
      )
      .max(maxColors),
  })
  .superRefine(({ colors }, context) => {
    for (const { field, index } of findRepeats(colors)) {
      context.addIssue({
        code: "custom",
        message: field === "id" ? "Each id must appear once" : "Another color has this title",
        path: ["colors", index, field],
      });
    }
  })
  .transform(({ colors }) => ({ colors: colors.toSorted(byTitle) }));

/**
 * The colors as stored in Firestore and as the API returns them, sorted by title. Only their
 * shape is checked: the rules above apply when the colors are saved, so tightening a rule later
 * never makes the saved colors unreadable. There are none until they are first saved.
 */
export const galleryColorsSchema = z.object({
  colors: z.array(z.object({ id: z.string(), title: z.string(), hex: z.string() })),
});

export type GalleryColors = z.infer<typeof galleryColorsSchema>;
